import json
from pathlib import Path
root=Path(__file__).resolve().parents[1];e=json.loads((root/'artifacts/evaluation.json').read_text());a=json.loads((root/'artifacts/audit.json').read_text())
lines=['# Evaluation report','','Final corrected run: 2026-10-08. Real data only. Earlier results before the same-second feature fix are superseded. Target, cleaning rules, holdouts and parameter search were unchanged.','',f"There are {a['usable_samples']:,} eligible recorded posting-to-removal episodes across {a['distinct_participant_traces']} distinct traces ({a['participants']} raw IDs). Trace 7 duplicates trace 6 and is excluded. Unknown removals, conflicting/overlapping identities and invalid order are not training targets. Valid zero and long durations remain.",'','Selection minimizes development participant-average MAE in original seconds. Grouped validation errors are averaged over participants equally; final tests do not select parameters or models. All models use identical strictly earlier outcome updates, including timestamp-group handling. Dynamic source histories are within participant. The historical baseline falls back to frozen training source/global medians.','']
def f(x):return '—' if x is None else f'{x:.3g}' if abs(x)>1e8 else f'{x:.2f}'
for name,v in e['experiments'].items():
 lines += [f"## Experiment {name}: "+('unseen participants' if name=='A' else 'future notifications for known users'),'',f"Training/development fit: {v['train_samples']:,} episodes. Final test: {v['test_samples']:,} episodes from {v['test_participants']} participants. Development winner: **{v['selected']}**, parameter {v['selected_parameter']}.",'']
 lines += ['A reserves entire participants with seed 42 and uses three grouped development folds. Test IDs: '+', '.join(v['design']['test_participants'])+'.' if name=='A' else 'B uses per-participant posting-time 60%/80% boundaries. Training labels must be removed strictly before each fit cutoff. Histories update during replay; model parameters never update on test. Boundary timestamps and episode IDs are saved in the frozen manifest.','', '| Model | Development mean user MAE | Test mean user MAE | Pooled test MAE | Median AE | RMSE | R² |','|---|---:|---:|---:|---:|---:|---:|']
 for c in v['comparisons']:
  m=c['held_out'];lines.append('| '+c['model']+' | '+' | '.join(f(x) for x in [c['development_participant_mae'],m['participant_average_mae_seconds'],m['mae_seconds'],m['median_absolute_error_seconds'],m['rmse_seconds'],m['r2']])+' |')
 lines+=['','All errors above are seconds. Pooled MAE gives frequent users greater weight; mean user MAE weights each participant equally. R² is supplementary and can be negative.','', '### Per-participant MAE for the selected model','','| Participant | Test MAE seconds |','|---|---:|']
 winner=next(c for c in v['comparisons'] if c['model']==v['selected'])
 for u,mae in winner['held_out']['per_participant_mae_seconds'].items():lines.append(f'| {u} | {f(mae)} |')
 lines+=['','### Development ablation','','Fixed gradient booster, identical manifests; scores average participant MAE within each fold then average folds. These ablations do not select the deployed model.','', '| Features | Fold-average user MAE seconds | Change from previous |','|---|---:|---:|'];last=None
 for row in v['ablations']:
  score=row['development_participant_mae'];delta=None if last is None else score-last;lines.append(f"| {row['features']} | {f(score)} | {f(delta)} |");last=score
 lines+=['','Negative changes improve MAE; positive changes worsen it. Each feature addition should be judged from these actual values, not assumed helpful.','', '### Held-out error analysis','','| Group | Samples | MAE seconds |','|---|---:|---:|']
 for group,r in {**v['diagnostics']['subgroups'],**v['diagnostics']['duration_ranges']}.items():lines.append(f"| {group} | {r['n']} | {f(r['mae_seconds'])} |")
 lines+=['','Duration range boundaries are computed from training only: '+', '.join(f(x) for x in v['diagnostics']['training_duration_boundaries_seconds'])+' seconds. Source frequency groups also use training counts only.', '',f"Prediction-versus-observed and signed-residual plots: `artifacts/{name}_diagnostics.png`. Full event predictions: `artifacts/{name}_predictions.csv`.",'']
lines+=['## Search, deployment and limitations','','Search: Ridge alpha 1/10; Random Forest minimum leaf size 5/20 (60 trees, max depth 12); histogram gradient boosting L2 1/10 (100 iterations, 15 leaves). All three regressors fit log1p targets and inverse-transform predictions. Negative predictions are clamped to zero. Imputation, encoding, scaling and target transformation fit within each training fold. Unknown source encoding and missing-history fallback are explicit.','', 'The deployed model is the B development-fit winner; the final B test is still held out. A baseline may legitimately win in another dataset. A Ridge validation error is extremely large under unseen-user extrapolation; it is retained transparently and was not selected. No fabricated accuracy or confidence percentage is reported.','', 'The sample is selected on observed, unambiguous recorded removal. No verified monitoring endpoints, Android tags, removal reasons or local timezones exist. Recorded posting may be a later update rather than first lifecycle posting. The population has only 13 distinct traces and A tests only three participants: notifications are not independent people. Per-participant results show variability but are not a confidence interval or proof of broad generalization. Long-duration errors remain substantial. Feature association is not causality.','', 'Unusual load uses a B-training 95th-percentile posting-count threshold; there are no anomaly labels or anomaly accuracy. Removal is not reading, attention or importance; unusual load is not fatigue. Synthetic simulator data never enters evaluation. Optional horizon classification and survival analysis are deferred for lack of verified follow-up.', '', 'Full audit, search fold metrics, manifests and metadata remain available in `artifacts/audit.json`, `evaluation.json`, `splits.json` and `model_metadata.json`.']
(root/'EVALUATION_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
